// The sync identifier must not be derivable from public provider details.
// A per-install random token is minted once and kept in local storage.
const getSyncKey = () => {
  let token = localStorage.getItem('doggy_sync_token');
  if (!token) {
    const bytes = crypto.getRandomValues(new Uint8Array(16));
    token = Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
    localStorage.setItem('doggy_sync_token', token);
  }
  const mainIdentity = xtreamUrl ? `${xtreamUrl}|${xtreamUser}` : m3uUrl;
  if (!mainIdentity) return null;
  return `favs_${token}`;
};

